"use strict";module.exports=function(defaultFuncs,api,ctx){const scheduledMessages=new Map;let nextId=1;function toTimestamp(when){if(when instanceof Date)return when.getTime();if(typeof when==="number")return when;if(typeof when==="string")return new Date(when).getTime();return NaN}function scheduleMessage(message,threadID,when,options){options=options||{};const timestamp=toTimestamp(when);if(isNaN(timestamp))throw new Error("Invalid 'when'. Must be Date, number (ms timestamp), or ISO string.");const now=Date.now();if(timestamp<=now)throw new Error("Scheduled time must be in the future.");const id=`scheduled_${nextId++}_${now}`;const delay=timestamp-now;const scheduled={id:id,message:message,threadID:threadID,timestamp:timestamp,createdAt:now,options:{replyMessageID:options.replyMessageID||null,callback:options.callback||null},cancelled:false,timeout:null};scheduled.timeout=setTimeout(()=>{if(scheduled.cancelled)return;const sendFn=api.sendMessage||api.sendMessageMqtt;if(!sendFn)return;Promise.resolve(sendFn(message,threadID,scheduled.options.callback||(()=>{}),scheduled.options.replyMessageID)).then(()=>{scheduledMessages.delete(id)}).catch(()=>{scheduledMessages.delete(id)})},delay);scheduledMessages.set(id,scheduled);return id}function cancelScheduledMessage(id){const s=scheduledMessages.get(id);if(!s||s.cancelled)return false;clearTimeout(s.timeout);s.cancelled=true;scheduledMessages.delete(id);return true}function getScheduledMessage(id){const s=scheduledMessages.get(id);if(!s||s.cancelled)return null;return{id:s.id,message:s.message,threadID:s.threadID,timestamp:s.timestamp,createdAt:s.createdAt,options:{...s.options},timeUntilSend:s.timestamp-Date.now()}}function listScheduledMessages(){const now=Date.now();return Array.from(scheduledMessages.values()).filter(s=>!s.cancelled).map(s=>({id:s.id,message:s.message,threadID:s.threadID,timestamp:s.timestamp,createdAt:s.createdAt,options:{...s.options},timeUntilSend:s.timestamp-now})).sort((a,b)=>a.timestamp-b.timestamp)}function cancelAllScheduledMessages(){let count=0;for(const id of Array.from(scheduledMessages.keys())){if(cancelScheduledMessage(id))count++}return count}function getScheduledCount(){return scheduledMessages.size}const cleanupInterval=setInterval(()=>{const now=Date.now();for(const[id,s]of scheduledMessages.entries()){if(s.cancelled||s.timestamp<now)scheduledMessages.delete(id)}},5*60*1e3);cleanupInterval.unref?.();function destroy(){clearInterval(cleanupInterval);return cancelAllScheduledMessages()}ctx._scheduler={destroy:destroy};return{scheduleMessage:scheduleMessage,cancelScheduledMessage:cancelScheduledMessage,getScheduledMessage:getScheduledMessage,listScheduledMessages:listScheduledMessages,cancelAllScheduledMessages:cancelAllScheduledMessages,getScheduledCount:getScheduledCount,destroy:destroy}};
